137	/**
138	 * Remove a temporary directory a test made, without failing the test over it.
139	 *
140	 * `rmSync(..., { force: true })` is not enough on Windows, where a directory a git
141	 * process touched stays locked for a moment after that process exits: the removal
142	 * throws `EBUSY`, from a `finally` block, after every assertion in the test has
143	 * already passed. `maxRetries` is exactly what Node added for that.
144	 *
145	 * And it still swallows what survives the retries. This is a temp directory the
146	 * operating system will clean up anyway; a test that cannot delete one has not found
147	 * anything about the code it was testing, and saying it failed would be false.
148	 */
149	export function removeTemp(dir: string): void {
150	  try {
151	    rmSync(dir, { recursive: true, force: true, maxRetries: 10, retryDelay: 50 });
152	  } catch {
153	    // The OS owns it now.
154	  }
155	}
