188	export function parseGithubOutput(text: string): Record<string, string> {
189	  const out: Record<string, string> = {};
190	  for (const line of text.split("\n")) {
191	    const eq = line.indexOf("=");
192	    if (eq === -1) continue;
193	    out[line.slice(0, eq)] = line.slice(eq + 1);
194	  }
