1	#!/usr/bin/env bun
2	/**
3	 * run_environment_setup.ts — Run each command in config.yaml's
4	 * `environment.setup_commands` (if any) via `bash -c`, before the agent
5	 * starts, so it never has to spend iterations/tool calls doing one-off
6	 * environment prep itself on a cold runner. No-ops quietly if unset/empty.
7	 *
8	 * Mirrors GitHub Actions' own default `bash -e {0}` semantics: the first
9	 * failing command aborts immediately with its exit code.
10	 */
11	import { loadConfig } from "../../adapters/runner/config.ts";
12	import { defineScript } from "./lib/script-ref.ts";
13	
14	export const ref = defineScript(import.meta.url);
15	
16	function main(): void {
17	  const commands = loadConfig().environment?.setup_commands ?? [];
18	  if (commands.length === 0) {
19	    console.log("No environment.setup_commands configured; skipping.");
20	    return;
21	  }
22	  for (const cmd of commands) {
23	    console.log(`Running environment setup command: ${cmd}`);
24	    const result = Bun.spawnSync({ cmd: ["bash", "-c", cmd], stdout: "inherit", stderr: "inherit" });
25	    if (result.exitCode !== 0) {
26	      console.error(`environment setup command failed (exit ${result.exitCode}): ${cmd}`);
27	      process.exit(result.exitCode ?? 1);
28	    }
29	  }
30	}
31	
32	if (import.meta.main) main();

