{"path": "tests/contract/test-hermetic-env.test.ts", "content": "/**
 * test-hermetic-env.test.ts — a test that spawns a script spawns it without the
 * variables that exist only inside an Atomaton run.
 *
 * ## The failure this exists for
 *
 * The runner sets `ATOMATON_MACHINERY_ROOT`, `ATOMATON_RUN_TYPE`, `ISSUE_NUMBER`,
 * `ATOMATON_OPS_LOG` and `ISSUE_NOTIFY` in the environment the agent works in, and a
 * test that spawns a child with `...process.env` hands them straight to it. The child
 * is then not reading the fixture the test wrote: `loadConfig()` resolves its path
 * through `machineryPath(CONFIG_FILE)`, so `ATOMATON_MACHINERY_ROOT` sends it to the
 * DEPLOYED config instead, and `ATOMATON_OPS_LOG` sends the shell guard's search
 * streak to the run's own live counter.
 *
 * The damage is not the failure itself, which is why CI stayed green through all of
 * it. It is that the agent cannot tell that red from one its own change caused, and
 * `harness.ts`'s own comment records the run that spent its remaining iterations
 * hunting one of these and never finished its task. Measured before this test: 3
 * failures in an agent's run and 0 in CI on the same commit.
 *
 * `hermeticEnv()` in `src/entrypoints/machinery/testing/harness.ts` is the fix, and it
 * is one line per call site. What is easy to leave out and not notice is the call
 * site: eleven files had it missing, and this repository has been here before --
 * the machinery-root test beside this one exists for a variable spelled by hand in a
 * second place. So this is the ratchet rather than the repair.
 *
 * ## What this can see, and what it cannot
 *
 * A `.test.ts` file that names `bun` as a spawn target must call `hermeticEnv()`
 * somewhere. That is file granularity, like `machinery-root.test.ts`: a file that
 * calls it once and spawns unhermetically twice passes. It catches the case that
 * happened -- a new subprocess test written from scratch with `...process.env` --
 * and not a half-fixed file, which is the honest limit of a text scan.
 *
 * It also cannot see a child spawned through an interpreter (`bash -c "bun run ..."`)
 * or one where the command is assembled from pieces. Nothing here does either.
 */
import { describe, expect, test } from "bun:test";
import { spawnSync } from "node:child_process";
import { mkdtempSync, readFileSync, readdirSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { hermeticEnv } from "../../src/entrypoints/machinery/testing/harness.ts";

/** A call that starts a child process. */
const SPAWNS = /(?:^|[^\w.])(?:spawn|spawnSync|execFileSync|execSync|execFile)\s*\(|Bun\.spawn(?:Sync)?\s*\(/;

/** A spawn target that is this repository's own runner, rather than `git` or `bash`. */
const RUNS_BUN = /["'`]bun["'`]/;

/** Every `.test.ts` under a directory, at any depth. */
function testFiles(dir: string): string[] {
  return readdirSync(dir, { recursive: true })
    .map(String)
    .map((name) => join(dir, name).replaceAll("\\", "/"))
    .filter((path) => path.endsWith(".test.ts"));
}

describe("a test that spawns a script", () => {
  test("does not hand it the run's own environment", () => {
    const offenders = [...testFiles("src"), ...testFiles("tests")]
      .filter((path) => {
        const source = readFileSync(path, "utf8");
        return SPAWNS.test(source) && RUNS_BUN.test(source) && !source.includes("hermeticEnv(");
      });

    expect(
      offenders,
      `import hermeticEnv() from src/entrypoints/machinery/testing/harness.ts and pass it as \`env\`; ` +
        `a child started with ...process.env reads the run's deployed config and the run's own ops log ` +
        `instead of this test's fixtures, which is red in an agent's run and green in CI: ${offenders.join(", ")}`,
    ).toEqual([]);
  });

  /**
   * The behavioural half, and the one that would have failed in CI on the original
   * defect. The scan above holds a file to the pattern; this holds the pattern to the
   * outcome, by running the suite that was red under the exact condition the runner
   * produces.
   *
   * Deterministic in CI too, because the variable is set here rather than inherited:
   * `makeConfigDir` writes a fixture whose setup command exits 1, and any test file
   * that lets its child inherit `ATOMATON_MACHINERY_ROOT` reads that instead of its
   * own fixture and reports the wrong thing.
   */
  test("survives ATOMATON_MACHINERY_ROOT pointing at another tree", () => {
    const decoy = mkdtempSync(join(tmpdir(), "atomaton-decoy-machinery-"));
    const nested = readFileSync("package.json", "utf8");
    try {
      // A deployed tree as the runner leaves one: a config.yaml whose setup command
      // cannot succeed where the test's fixture ran.
      const { makeConfigDir } = require("../../src/entrypoints/machinery/testing/harness.ts") as typeof import("../../src/entrypoints/machinery/testing/harness.ts");
      const tree = makeConfigDir({ environment: { setup_commands: ["exit 1"] } });
      try {
        const r = spawnSync(
          "bun",
          ["test", join(process.cwd(), "src/entrypoints/machinery/run_environment_setup.test.ts")],
          {
            encoding: "utf8",
            env: { ...hermeticEnv(), ATOMATON_MACHINERY_ROOT: tree },
            timeout: 60_000,
          },
        );
        expect(nested, "package.json must be readable, or this proves nothing").toBeString();
        expect(
          r.status,
          `the suite is red with ATOMATON_MACHINERY_ROOT set, so an agent cannot tell its own ` +
            `breakage from this one:\n${r.stdout}\n${r.stderr}`,
        ).toBe(0);
      } finally {
        rmSync(tree, { recursive: true, force: true });
      }
    } finally {
      rmSync(decoy, { recursive: true, force: true });
    }
  }, 90_000);
});
